-- MT translations
INSERT INTO vocabulary_translations (vocabulary_id, language_code, translated_word)
SELECT v.id, 'mt', t.translated_word
FROM vocabulary v
JOIN (VALUES
  ('walk', 'imxi'),
  ('run', 'ġri'),
  ('jump', 'aqbeż'),
  ('hop', 'aqbeż'),
  ('skip', 'aqbeż'),
  ('crawl', 'kaxkar'),
  ('climb', 'itla'''),
  ('slide', 'żelaq'),
  ('swing', 'tbandal'),
